def _terminal_validation_record(
    config: Config,
    raw: str,
    target: Path,
    target_kind: str,
    *,
    expected_digest: str | None = None,
    repository: Path | None = None,
    expected_target: str | None = None,
    allow_historical_service_result: bool = False,
    frozen_removal_proof_supplied: bool | None = None,
) -> tuple[str, str, str | None]:
    relative, path = _relative_inside(config.root, raw, "terminal validation record")
    if Path(relative).parent != Path("ignored/validate/runs") or path.suffix != ".json":
        raise Refusal("terminal validation record must be an ignored/validate/runs/*.json file")
    try:
        contents = _read_bounded_regular_file(
            path, "terminal validation record", 16 * 1024 * 1024
        )
        value = json.loads(contents)
    except (OSError, json.JSONDecodeError) as exc:
        raise Refusal(f"terminal validation record is unreadable: {path}: {exc}") from exc
    digest = hashlib.sha256(contents).hexdigest()
    if expected_digest is not None and digest != expected_digest:
        raise Refusal("terminal validation record changed after recovery was authorized")
    record = _as_mapping(value, "terminal validation record")
    field = (
        "checkout"
        if target_kind in {"checkout", "frozen-checkout"}
        else "cargo_home"
    )
    if target_kind != "frozen-checkout":
        recorded = record.get(field)
        if not isinstance(recorded, str) or recorded != str(target):
            raise Refusal(f"terminal validation record does not name this exact {field}")
        if target_kind == "checkout" and record.get("temporary_checkout") is False:
            raise Refusal("terminal validation record says the checkout is not temporary")
    record_target: str | None = None
    if target_kind == "frozen-checkout":
        if (
            frozen_removal_proof_supplied is False
            and not (
                type(record.get("service_result_schema")) is int
                and record.get("service_result_schema") in {1, 2, 3}
                and record.get("result_source") == "validation-service-result"
            )
        ):
            raise Refusal(
                "direct frozen validation recovery requires "
                "--validation-proof-manifest for current or historical-projection "
                "records; use the bounded batch command to classify a pre-proof "
                "historical checkout without removing it"
            )
        record_target = _frozen_validation_record_binding(
            record,
            target,
            repository,
            expected_target=expected_target,
        )
        if (
            record.get("schema_version") != 1
            or record.get("kind") != "frozen-validate"
            or record.get("producer") != "ci-hub/validate/run_registry.py"
            or record.get("admission") != "frozen-validate"
            or record.get("validation_kind") != "frozen-validate"
        ):
            raise Refusal(
                "terminal validation record is not an authoritative frozen-validation "
                "handle; preserve the checkout and pass its current frozen run handle"
            )
        projected, rebound = _canonical_frozen_validation_record(config, path, contents)
        _frozen_validation_record_binding(
            rebound,
            target,
            repository,
            expected_target=record_target,
        )
        if (
            projected.get("schema_version") != record.get("schema_version")
            or projected.get("kind") != "frozen-validate"
            or projected.get("state") != record.get("state")
            or projected.get("target") != record_target
            or projected.get("repo") != record.get("repo")
        ):
            raise Refusal(
                "canonical frozen validation record projection does not bind this handle"
            )
    if not _validation_record_is_terminal(
        record,
        target_kind=target_kind,
        allow_historical_service_result=allow_historical_service_result,
    ):
        raise Refusal(
            "validation record does not contain an evidenced terminal result; no path was "
            "removed. Let validate-run finish recording the result or preserve the path"
        )
    return relative, digest, record_target


def _validation_record_has_typed_admission(record: Mapping[str, object]) -> bool:
    """Return whether a current validation handle records a complete admission result."""

    kind = record.get("kind")
    frozen = kind == "frozen-validate"
    if (
        type(record.get("schema_version")) is not int
        or record.get("schema_version") != 1
        or not isinstance(kind, str)
        or kind not in {"validate", "reverie-validate", "frozen-validate"}
        or record.get("producer") != "ci-hub/validate/run_registry.py"
        or record.get("admission")
        != ("frozen-validate" if frozen else "ci-hub validate-lock")
        or record.get("temporary_checkout") is not True
        or (
            frozen
            and record.get("validation_kind") != "frozen-validate"
        )
    ):
        return False
    raw = record.get("admission_result")
    if not isinstance(raw, dict):
        return False
    state = raw.get("state")
    if state == "admitted":
        if not {"state", "recorded_at"} <= set(raw) or not set(raw) <= {
            "state",
            "recorded_at",
            "run_number",
        }:
            return False
        run_number = raw.get("run_number")
        if run_number is not None and (
            not isinstance(run_number, int)
            or isinstance(run_number, bool)
            or run_number <= 0
        ):
            return False
    elif state == "refused":
        if set(raw) != {"state", "recorded_at", "reason", "exit_code"}:
            return False
        reason = raw.get("reason")
        if not isinstance(reason, str) or reason not in {
            "stale-base",
            "validation-lock-refusal",
        }:
            return False
        exit_code = raw.get("exit_code")
        if (
            not isinstance(exit_code, int)
            or isinstance(exit_code, bool)
            or exit_code == 0
        ):
            return False
    else:
        return False
    recorded_at = raw.get("recorded_at")
    if not isinstance(recorded_at, str):
        return False
    try:
        _parse_timestamp(recorded_at, "validation admission result")
    except StateError:
        return False
    return True


def _validation_record_process_is_dead(record: Mapping[str, object]) -> bool:
    """Prove that the exact process generation recorded by a validation is gone."""

    raw = record.get("process_identity")
    if not isinstance(raw, dict) or set(raw) != {"pid", "start_ticks", "boot_id"}:
        return False
    pid = raw.get("pid")
    start_ticks = raw.get("start_ticks")
    boot_id = raw.get("boot_id")
    if (
        not isinstance(pid, int)
        or isinstance(pid, bool)
        or pid <= 0
        or not isinstance(start_ticks, int)
        or isinstance(start_ticks, bool)
        or start_ticks <= 0
        or not isinstance(boot_id, str)
        or not boot_id.strip()
    ):
        return False
    try:
        current_boot = _boot_id(Path("/proc"))
        process = _read_process_stat(Path("/proc") / str(pid))
    except Refusal:
        return False
    return current_boot != boot_id or process is None or process.start_ticks != start_ticks


def _current_validation_result_is_terminal(
    record: Mapping[str, object], *, schema: int, status: str
) -> bool:
    """Require every current result field that makes cleanup authoritative."""

    expected_results = {
        "PASSED": "success",
        "FAILED": "failure",
        "COULD_NOT_RUN": "no-result",
    }
    expected_result = expected_results.get(status)
    if expected_result is None or record.get("result") != expected_result:
        return False
    if record.get("result_source") != "validation-service-result":
        return False
    if "selection_mode" not in record:
        return False
    selection_mode = record.get("selection_mode")
    if selection_mode is not None and (
        not isinstance(selection_mode, str) or not selection_mode.strip()
    ):
        return False
    if (
        "executed_nodes" not in record
        or "scorecard_writeback" not in record
        or "executed_tests" not in record
        or "passed_tests" not in record
    ):
        return False
    writeback = record.get("scorecard_writeback")
    if writeback is not None:
        if not isinstance(writeback, dict):
            return False
        if writeback == {"status": "completed"}:
            pass
        elif (
            set(writeback) == {"status", "error"}
            and writeback.get("status") == "failed"
            and isinstance(writeback.get("error"), str)
            and bool(str(writeback["error"]).strip())
        ):
            pass
        else:
            return False
    executed_nodes = record.get("executed_nodes")
    if (
        not isinstance(executed_nodes, int)
        or isinstance(executed_nodes, bool)
        or executed_nodes < 0
    ):
        return False
    executed_tests = record.get("executed_tests")
    passed_tests = record.get("passed_tests")
    if executed_tests is not None and (
        not isinstance(executed_tests, int)
        or isinstance(executed_tests, bool)
        or executed_tests < 0
    ):
        return False
    if passed_tests is not None and (
        not isinstance(passed_tests, int)
        or isinstance(passed_tests, bool)
        or passed_tests < 0
    ):
        return False
    if (executed_tests is None) != (passed_tests is None):
        return False
    if (
        executed_tests is not None
        and passed_tests is not None
        and passed_tests > executed_tests
    ):
        return False
    if status == "PASSED" and (
        passed_tests is None or passed_tests != executed_tests
    ):
        return False
    if schema == 5:
        if "detail" not in record:
            return False
        detail = record.get("detail")
        if status == "COULD_NOT_RUN":
            if not isinstance(detail, str) or not detail.strip():
                return False
        elif detail is not None:
            return False
    elif "detail" in record:
        return False
    if (
        status == "PASSED"
        and isinstance(writeback, dict)
        and writeback.get("status") == "failed"
    ):
        expected_exit = 75
    else:
        expected_exit = {"PASSED": 0, "FAILED": 1, "COULD_NOT_RUN": 75}[status]
    exit_code = record.get("exit_code")
    return (
        isinstance(exit_code, int)
        and not isinstance(exit_code, bool)
        and exit_code == expected_exit
    )


def _historical_validation_result_is_terminal(
    record: Mapping[str, object], *, schema: int
) -> bool:
    """Recognize the exact non-authoritative projection of a finished sidecar."""

    status = record.get("final_validate_status")
    outcome = (
        _VALIDATION_RESULT_OUTCOMES.get(status)
        if isinstance(status, str)
        else None
    )
    if outcome is None:
        return False
    expected_exit = outcome[1]
    exit_code = record.get("exit_code")
    executed_nodes = record.get("executed_nodes")
    executed_tests = record.get("executed_tests")
    if (
        record.get("state") != "unknown"
        or record.get("result") != "unknown"
        or record.get("result_source") != "historical-validation-service-result"
        or record.get("detail") != _historical_validation_result_detail(schema)
        or record.get("passed_tests") is not None
        or type(exit_code) is not int
        or exit_code != expected_exit
        or type(executed_nodes) is not int
        or executed_nodes < 0
        or (
            executed_tests is not None
            and (type(executed_tests) is not int or executed_tests < 0)
        )
    ):
        return False
    if schema == 1:
        if "scorecard_writeback" in record:
            return False
    elif record.get("scorecard_writeback") != {"status": "completed"}:
        return False
    if schema == 3:
        if "selection_mode" not in record:
            return False
        selection_mode = record.get("selection_mode")
        return selection_mode is None or (
            isinstance(selection_mode, str) and bool(selection_mode.strip())
        )
    return "selection_mode" not in record


def _validation_record_is_terminal(
    record: Mapping[str, object],
    *,
    target_kind: str,
    allow_historical_service_result: bool = False,
) -> bool:
    """Return whether one retained validation handle proves execution has stopped.

    A current handle may retain an unknown validation verdict after its service
    result was lost.  Its exact process generation being gone still proves that
    disposable validation storage is no longer owned by that execution.  This
    cleanup fact does not promote the unknown verdict to passed or failed.
    """

    schema = record.get("service_result_schema")
    if record.get("result_source") == "validation-service-result" and schema is None:
        return False
    if (
        allow_historical_service_result
        and type(schema) is int
        and schema in {1, 2, 3}
    ):
        return _historical_validation_result_is_terminal(record, schema=schema)

    state = record.get("state")
    if not isinstance(state, str):
        return False
    if state in {"killed", "not-run", "refused"}:
        return True
    if state != "completed":
        return bool(
            target_kind in {"cargo-home", "frozen-checkout"}
            and state == "unknown"
            and record.get("result") == "unknown"
            and isinstance(record.get("detail"), str)
            and str(record["detail"]).strip()
            and _validation_record_has_typed_admission(record)
            and _validation_record_process_is_dead(record)
        )
    exits = {"PASSED": 0, "FAILED": 1, "COULD_NOT_RUN": 75}
    status = record.get("final_validate_status")
    expected_exit = exits.get(status) if isinstance(status, str) else None
    if schema is not None and (
        not isinstance(schema, int)
        or isinstance(schema, bool)
        or schema not in {1, 2, 3, 4, 5}

    record_relative, record_path = _validation_run_record_argument(
        config, raw_record
    )
    record_contents, record_identity = _read_regular_file_identity(
        record_path,
        "historical frozen validation run-record",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    record = _strict_json_object(
        record_contents, "historical frozen validation run-record"
    )
    _repository_relative, repository = _repository_path(
        config, raw_repository, allow_managed=True
    )
    schema = record.get("service_result_schema")
    result_source = record.get("result_source")
    if (
        type(schema) is int
        and schema in {1, 2, 3}
        and result_source == "validation-service-result"
    ):
        return _FrozenNoProofClassification(
            _FrozenNoProofDisposition.LEGACY_RECOVERY
        )
    if (
        type(schema) is not int
        or schema not in {2, 3}
        or result_source != "historical-validation-service-result"
    ):
        _terminal_validation_record(
            config,
            record_relative,
            checkout,
            "frozen-checkout",
            repository=repository,
        )
        if _current_incomplete_frozen_result(record):
            return _current_incomplete_frozen_retention(
                config, checkout, record_path, record_contents, record_identity,
                repository, batch_cleanup=batch_cleanup,
            )
        return _FrozenNoProofClassification(
            _FrozenNoProofDisposition.BLOCKS_ENTRY
        )
    if (
        record.get("kind") != "frozen-validate"
        or record.get("materialized_target") is not False
        or "scorecard_handoff" in record
        or "scorecard_writeback_files" in record
    ):
        raise Refusal(
            "historical frozen validation without a removal proof does not match "
            "the pre-proof non-materialized shape"
        )
    if not _validation_record_process_is_dead(record):
        raise Refusal(
            "historical frozen validation process state is live or uncertain"
        )

    _record_relative, record_digest, record_target = _terminal_validation_record(
        config,
        record_relative,
        checkout,
        "frozen-checkout",
        repository=repository,
        allow_historical_service_result=True,
    )
    if record_target is None:
        raise StateError("historical frozen validation has no exact target")
    _validation_checkout_facts(
        config,
        checkout,
        repository,
        expected_head=record_target,
        batch_cleanup=batch_cleanup,
        fresh_same_uid=False,
        standalone=True,
        remote_observation_repository=repository,
        require_remote_containment=False,
    )

    producer_path = checkout / _VALIDATION_SERVICE_RESULT_SCHEMA_PATH
    sidecar_path = record_path.with_name(
        f"{record_path.stem}{_VALIDATION_SERVICE_RESULT_SUFFIX}"
    )
    _ensure_no_symlink_components(
        checkout, producer_path, "historical frozen validation producer schema"
    )
    producer_contents, producer_identity = _read_regular_file_identity(
        producer_path,
        "historical frozen validation producer schema",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    sidecar_contents, sidecar_identity = _read_regular_file_identity(
        sidecar_path,
        "historical frozen validation service-result",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    schema_fields = _validation_service_result_schema(producer_contents, schema)
    projection = _validation_service_result_projection(
        sidecar_contents,
        schema=schema,
        schema_fields=schema_fields,
        expected_commit=record_target,
    )
    for field, expected in projection.items():
        if field not in record or not _json_equal(record[field], expected):
            raise Refusal(
                f"historical frozen validation service-result {field} differs "
                "from the run-record"
            )
    if projection.get("scorecard_writeback") != {"status": "completed"}:
        raise Refusal(
            "historical frozen validation has no completed scorecard writeback"
        )

    # The decision is made only after a fresh same-UID census and a second read
    # of every authority-bearing file.  Any changed or unreadable observation
    # remains an entry blocker; no destructive action follows this proof.
    batch_cleanup.assert_unused(config, checkout, fresh_same_uid=True)
    rebound_record, rebound_record_identity = _read_regular_file_identity(
        record_path,
        "historical frozen validation run-record",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    rebound_producer, rebound_producer_identity = _read_regular_file_identity(
        producer_path,
        "historical frozen validation producer schema",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    rebound_sidecar, rebound_sidecar_identity = _read_regular_file_identity(
        sidecar_path,
        "historical frozen validation service-result",
        _VALIDATION_REMOVAL_ARTIFACT_BYTES_LIMIT,
    )
    _assert_regular_file_identity(
        record_identity,
        rebound_record_identity,
        "historical frozen validation run-record",
    )
    _assert_regular_file_identity(
        producer_identity,
        rebound_producer_identity,
        "historical frozen validation producer schema",
    )
    _assert_regular_file_identity(
        sidecar_identity,
        rebound_sidecar_identity,
        "historical frozen validation service-result",
    )
    if (
        rebound_record != record_contents
        or rebound_producer != producer_contents
        or rebound_sidecar != sidecar_contents
    ):
        raise Refusal(
            "historical frozen validation evidence changed during entry classification"
        )
    _terminal_validation_record(
        config,
        record_relative,
        checkout,
        "frozen-checkout",
        expected_digest=record_digest,
        repository=repository,
        expected_target=record_target,
        allow_historical_service_result=True,
    )
    if _GitVcs().head(checkout) != record_target:
        raise Refusal(
            "historical frozen validation checkout HEAD changed during entry "
            "classification"
        )
    return _FrozenNoProofClassification(
        _FrozenNoProofDisposition.HISTORICAL_NONBLOCKING,
        historical_schema=schema,
    )


def _recordless_validation_evidence(
    config: Config, target: Path, target_kind: str, note: str | None
) -> Mapping[str, object]:
    if note is None or not note.strip():
        raise Refusal("recordless validation recovery requires a non-empty --recovery-note")
    field = (
        "checkout"
        if target_kind in {"checkout", "frozen-checkout"}
        else "cargo_home"
    )
    records = config.root / "ignored" / "validate" / "runs"
    if records.is_symlink() or (records.exists() and not records.is_dir()):
        raise Refusal(f"retained validation record directory is unsafe: {records}")
    for path in sorted(records.glob("*.json")) if records.is_dir() else ():
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise Refusal(f"cannot prove retained record is unrelated: {path}: {exc}") from exc
        if not isinstance(value, dict):
            raise Refusal(f"cannot prove retained record is unrelated: {path} is not an object")
        recorded = value.get(field)
        if isinstance(recorded, str) and Path(recorded).resolve() == target:
            raise Refusal(
                f"retained validation record {path} names this {field}; use --completed-record"
            )
    return {"kind": "coordinator-determination", "note": note.strip(), "no_retained_record": True}


def _ownerless_validation_blocking_status(
    status: str, cache_globs: Sequence[str]
) -> str:
    """Keep every porcelain record except ignored paths under explicit safe roots."""

    blocking: list[str] = []
    for record in status.splitlines():
        if record.startswith("! "):
            path = record[2:]
            if any(_cache_glob_contains_path(pattern, path) for pattern in cache_globs):
                continue
        blocking.append(record)
    return "\n".join(blocking)


def _validation_checkout_facts(
    config: Config,
    checkout: Path,
    repository: Path,
    *,
    expected_head: str | None = None,
    expected_remote: str | None = None,
    batch_cleanup: _OwnerlessValidationBatchContext | None = None,
    fresh_same_uid: bool = False,
    standalone: bool = False,
    remote_observation_repository: Path | None = None,
    require_remote_containment: bool = True,
) -> tuple[str, str]:
    if repository == checkout or _path_is_within(repository, checkout):
        raise Refusal("repository must survive removal and cannot be inside the checkout")
    if checkout.is_symlink() or not checkout.is_dir():
        raise Refusal(f"validation checkout is absent or unsafe: {checkout}")
    _ensure_no_mount_components(checkout.parent, checkout, "validation checkout")
    _assert_no_mountinfo_crossing(checkout, checkout, "validation checkout")
    if (checkout / "HANDOFF.md").exists() or (checkout / "HANDOFF.md").is_symlink():
        raise Refusal(f"validation checkout contains HANDOFF.md: {checkout}")
    vcs = _GitVcs()
    if standalone:
        if (
            vcs.repository_root(checkout) != checkout.absolute()
            or (checkout / ".git").is_symlink()
            or not (checkout / ".git").is_dir()
        ):
            raise Refusal(
                f"frozen validation checkout is not a standalone Git clone: {checkout}"
            )
        head = vcs.head(checkout)
    else:
        head = vcs.verify_existing_worktree(repository, checkout)
    if expected_head is not None and head != expected_head:
        raise Refusal(
            "validation checkout HEAD changed after recovery was authorized; preserve the "
            "checkout and restore the recorded target before retrying"
        )
    vcs.assert_ordinary_history(checkout)
    vcs.assert_ordinary_index(checkout)
    _assert_cache_policy_untracked_path(
        config, "ownerless-validation", checkout, vcs, config.cache_globs
    )
    preserve_checkout_git_state = (
        remote_observation_repository is not None or not require_remote_containment
    )
    status = _ownerless_validation_blocking_status(
        vcs.status(
            checkout,
            config.cache_globs,
            refresh_index=not preserve_checkout_git_state,
        ),
        ("ignored", *config.cache_globs),
    )
    if status:
        raise Refusal(f"validation checkout is dirty ({status.splitlines()[0]}); preserve it")
    remote = config.default_remote
    landed_ref = _landed_ref_for_remote(config, remote)
    remote_digest = vcs.remote_url_sha256(checkout, remote)
    repository_remote_digest = (
        vcs.remote_url_sha256(repository, remote)
        if standalone or remote_observation_repository is not None
        else None
    )
    if standalone and repository_remote_digest != remote_digest:
        raise Refusal(
            "frozen validation checkout remote differs from its recorded source checkout; "
            "preserve both checkouts and repair their origin binding before retrying"
        )
    if expected_remote is not None and remote_digest != expected_remote:
        raise Refusal("validation checkout remote changed after recovery was authorized")
    remote_observer = checkout
    if remote_observation_repository is not None:
        remote_observer = remote_observation_repository
        if remote_observer == checkout or _path_is_within(remote_observer, checkout):
            raise StateError(
