def _json_equal(left: object, right: object) -> bool:
    return json.dumps(
        left, sort_keys=True, separators=(",", ":"), ensure_ascii=True
    ) == json.dumps(right, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def _recover_config_write(path: Path, payload: object) -> None:
    leftovers = sorted(path.parent.glob(f"{path.name}.tmp.*"))
    if not leftovers:
        return
    if path.exists() or path.is_symlink():
        existing = _as_mapping(_read_json(path, "configuration"), "configuration")
        if dict(existing) != payload:
            raise StateError(
                f"configuration temp file exists beside a different durable configuration: {leftovers[0]}"
            )
        for leftover in leftovers:
            leftover.unlink()
        _fsync_directory(path.parent)
        return
    matching: list[Path] = []
    for leftover in leftovers:
        try:
            candidate = _read_json(leftover, "configuration temp file")
        except StateError:
            leftover.unlink()
            continue
        if candidate != payload:
            raise StateError(
                f"configuration temp file records different init input: {leftover}"
            )
        matching.append(leftover)
    if len(matching) > 1:
        raise StateError("multiple complete configuration temp files require inspection")
    if matching:
        os.replace(matching[0], path)
        _fsync_directory(path.parent)
    else:
        _fsync_directory(path.parent)

def _cmd_recover_ownerless_validate_batch(args: argparse.Namespace) -> int:
    ordinary_checkouts = tuple(args.checkouts or ())
    frozen_checkouts = tuple(args.frozen_validate_checkouts or ())
    if bool(ordinary_checkouts) == bool(frozen_checkouts):
        raise Refusal(
            "recover-ownerless-validate-batch requires exactly one of --checkout or "
            "--frozen-validate-checkout; choose the matching validation storage kind and retry"
        )
    frozen = bool(frozen_checkouts)
    checkouts = frozen_checkouts if frozen else ordinary_checkouts
    records = tuple(args.completed_records)
    repositories = tuple(args.repositories)
    proof_manifests = tuple(
        getattr(args, "validation_proof_manifests", ()) or ()
    )
    if not (len(checkouts) == len(records) == len(repositories)):
        raise Refusal(
            "recover-ownerless-validate-batch requires the same number of "
            "--checkout, --completed-record, and --repository arguments"
        )
    if proof_manifests and len(proof_manifests) != len(checkouts):
        raise Refusal(
            "recover-ownerless-validate-batch requires one "
            "--validation-proof-manifest for each checkout when any proof is supplied"
        )
    if len(checkouts) > VALIDATE_REMOVE_BATCH_LIMIT:
        raise Refusal(
            "recover-ownerless-validate-batch accepts at most "
            f"{VALIDATE_REMOVE_BATCH_LIMIT} checkouts"
        )
    if len(set(checkouts)) != len(checkouts):
        raise Refusal(
            "recover-ownerless-validate-batch received the same checkout more than once"
        )
    _require_coordinator_authorized(args, "ownerless validation cleanup")
    config = _load_config(args.project_root, args.machine)
    canonical_proofs = tuple(
        _validation_proof_manifest_path(config, raw)[0]
        for raw in proof_manifests
    )
    if len(canonical_proofs) != len(set(canonical_proofs)):
        raise Refusal(
            "recover-ownerless-validate-batch received the same validation proof "
            "manifest more than once"
        )
    aligned_proofs: tuple[str | None, ...] = (
        tuple(canonical_proofs)
        if canonical_proofs
        else tuple(None for _checkout in checkouts)
    )
    _capture_caller_process(args.coordinator_pid, "coordinator")
    retained: list[dict[str, object]] = []
    removed: list[dict[str, object]] = []
    prepared: list[
        tuple[str, str, str, str | None, Path, _PrivateCleanupIdentity]
    ] = []
    with _mutation_locks(config, args.wait_lock):
        _refuse_partial_state(config, allow_validate_batch_seals=True)
        if _outstanding_journals(config) or _validate_batch_seal_journals(config):
            raise Refusal(
                "an interrupted mutation is already recorded; recover it before starting "
                "ownerless validation batch cleanup"
            )
        for checkout, record, repository, proof_manifest in zip(
            checkouts,
            records,
            repositories,
            aligned_proofs,
            strict=True,
        ):
            try:
                _relative, target, _allowed = _validation_recovery_target(
                    config,
                    checkout,
                    "frozen-checkout" if frozen else "checkout",
                )
                identity = _private_cleanup_path_identity(
                    config,
                    target,
                    allowed_modes={0o700},
                    managed_root=(
                        _frozen_validation_directory(config) if frozen else None
                    ),
                )
            except (Refusal, StateError) as exc:
                retained.append(
                    {
                        "blocks_entry": True,
                        "checkout": checkout,
                        "reason": str(exc),
                    }
                )
            else:
                prepared.append(
                    (
                        checkout,
                        record,
                        repository,
                        proof_manifest,
                        target,
                        identity,
                    )
                )
    identities = [identity for *_prefix, identity in prepared]
    if len(set(identities)) != len(identities):
        raise Refusal(
            "recover-ownerless-validate-batch resolved multiple checkouts to one directory"
        )
    census_budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=_VALIDATE_REMOVE_BATCH_CENSUS_SECONDS,
        stdout_limit=16 * 1024 * 1024,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    shared_census_count = int(bool(prepared))
    if prepared:
        try:
            shared_census = _capture_lsof_process_path_census(
                [target for *_prefix, target, _identity in prepared],
                budget=census_budget,
            )
            census_budget.remaining_seconds()
        except Refusal as exc:
            retained.extend(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                }
                for checkout, _record, _repository, _proof, _target, _identity in prepared
            )
            prepared = []
            shared_census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    else:
        shared_census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    batch_cleanup = _OwnerlessValidationBatchContext(
        {identity: target for *_prefix, target, identity in prepared},
        shared_census,
        census_budget,
    )
    for index, (
        checkout,
        record,
        repository,
        proof_manifest,
        target,
        _identity,
    ) in enumerate(prepared):
        try:
            census_budget.remaining_seconds()
            shared_census.assert_slot_unused(
                target, None, ignore_current_process=False
            )
            if frozen and proof_manifest is None:
                classification = _frozen_no_proof_disposition(
                    config,
                    target,
                    record,
                    repository,
                    batch_cleanup=batch_cleanup,
                )
                if classification.disposition is _FrozenNoProofDisposition.CURRENT_INCOMPLETE_RETAINED:
                    retained.append({
                        "blocks_entry": False,
                        "checkout": checkout,
                        "reason": "current incomplete frozen validation is exact and inactive; the checkout and no-result remain retained",
                    })
                    continue
                if (
                    classification.disposition
                    is not _FrozenNoProofDisposition.LEGACY_RECOVERY
                ):
                    nonblocking = (
                        classification.disposition
                        is _FrozenNoProofDisposition.HISTORICAL_NONBLOCKING
                    )
                    historical_schema = classification.historical_schema
                    if nonblocking and historical_schema is None:
                        raise StateError(
                            "historical frozen validation classification lost its schema"
                        )
                    retained.append(
                        {
                            "blocks_entry": not nonblocking,
                            "checkout": checkout,
                            "reason": (
                                f"historical schema {historical_schema} frozen validation has no "
                                "removal proof; the inactive checkout remains retained"
                                if nonblocking
                                else "frozen validation has no typed removal proof; "
                                "the checkout remains retained and blocks entry"
                            ),
                        }
                    )
                    continue
            item_args = argparse.Namespace(
                project_root=args.project_root,
                machine=args.machine,
                wait_lock=args.wait_lock,
                command="recover",
                coordinator_pid=args.coordinator_pid,
                coordinator_authorized=True,
                discard_partial=False,
                legacy_validate_checkout=checkout,
                ownerless_validate_checkout=None,
                ownerless_validate_cargo_home=None,
                frozen_validate_checkout=checkout if frozen else None,
                completed_record=record,
                repository=repository,
                validation_proof_manifest=proof_manifest,
                recovery_note=None,
                retry_running_hook=False,
                abort_create=False,
            )
            if frozen:
                item_args.legacy_validate_checkout = None
                item_args.ownerless_validate_checkout = None
            _cmd_recover(
                item_args,
                ownerless_batch_cleanup=batch_cleanup,
                emit=False,
            )
        except (Refusal, StateError) as exc:
            retained.append(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                }
            )
            if _outstanding_journals(config) or _validate_batch_seal_journals(config):
                reason = (
                    "an interrupted mutation remains after the preceding refusal; "
                    "recover it before retrying this checkout"
                )
                retained.extend(
                    {
                        "blocks_entry": True,
                        "checkout": remaining[0],
                        "reason": reason,
                    }
                    for remaining in prepared[index + 1 :]
                )
                break
        else:
            removed.append({"checkout": checkout})
    payload = {
        "schema": 2,
        "batch_limit": VALIDATE_REMOVE_BATCH_LIMIT,
        "process_censuses": shared_census_count,
        "shared_process_censuses": shared_census_count,
        "same_uid_process_censuses": batch_cleanup.same_uid_census_count,
        "requested": len(checkouts),
        "removed": removed,
        "retained": retained,
    }
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        print(
            f"requested={len(checkouts)} removed={len(removed)} "
            f"retained={len(retained)} process_censuses={shared_census_count}"
        )
        for row in retained:
            print(
                f"RETAINED: {row['checkout']} "
                f"blocks_entry={str(row['blocks_entry']).lower()} "
                f"reason={row['reason']}"
            )
    return 0


def _cmd_classify_ownerless_validate_batch(args: argparse.Namespace) -> int:
    """Classify retained validation checkouts without locks or writes."""

    ordinary = tuple(args.checkouts or ())
    frozen_values = tuple(args.frozen_validate_checkouts or ())
    if bool(ordinary) == bool(frozen_values):
        raise Refusal(
            "classify-ownerless-validate-batch requires exactly one of --checkout or "
            "--frozen-validate-checkout"
        )
    frozen = bool(frozen_values)
    checkouts = frozen_values if frozen else ordinary
    records = tuple(args.completed_records)
    repositories = tuple(args.repositories)
    proofs = tuple(args.validation_proof_manifests or ())
    if not (len(checkouts) == len(records) == len(repositories)):
        raise Refusal(
            "classify-ownerless-validate-batch requires the same number of "
            "checkout, completed-record, and repository arguments"
        )
    if proofs and len(proofs) != len(checkouts):
        raise Refusal(
            "classify-ownerless-validate-batch requires one proof per checkout"
        )
    if len(checkouts) > VALIDATE_REMOVE_BATCH_LIMIT:
        raise Refusal(
            "classify-ownerless-validate-batch accepts at most "
            f"{VALIDATE_REMOVE_BATCH_LIMIT} checkouts"

        )
    if len(set(checkouts)) != len(checkouts):
        raise Refusal(
            "classify-ownerless-validate-batch received a duplicate checkout"
        )
    config = _load_config(args.project_root, args.machine)
    canonical_proofs = tuple(
        _validation_proof_manifest_path(config, value)[0] for value in proofs
    )
    if len(canonical_proofs) != len(set(canonical_proofs)):
        raise Refusal("classify-ownerless-validate-batch received a duplicate proof")
    aligned_proofs: tuple[str | None, ...] = (
        canonical_proofs
        if canonical_proofs
        else tuple(None for _checkout in checkouts)
    )
    _refuse_partial_state(config, allow_validate_batch_seals=True)
    if _validate_batch_seal_journals(config):
        raise Refusal(
            "an interrupted validation-batch seal is recorded; recover it before admission"
        )
    before_states, before_archives = _validate_global_state(config)
    before_rows = _global_rows(before_states, before_archives)
    before_paths = tuple(_outstanding_journals(config))
    create_rows = _classify_create_journals(
        config, before_states, before_archives
    )
    prepared: list[
        tuple[str, str, str, str | None, Path, _PrivateCleanupIdentity]
    ] = []
    results: list[dict[str, object]] = []
    for checkout, record, repository, proof in zip(
        checkouts, records, repositories, aligned_proofs, strict=True
    ):
        try:
            _relative, target, _allowed = _validation_recovery_target(
                config,
                checkout,
                "frozen-checkout" if frozen else "checkout",
            )
            if any(
                _path_is_within(target, row.slot_path)
                or _path_is_within(row.slot_path, target)
                for row in create_rows
            ):
                raise Refusal("validation path overlaps an interrupted create")
            identity = _private_cleanup_path_identity(
                config,
                target,
                allowed_modes={0o700},
                managed_root=(
                    _frozen_validation_directory(config) if frozen else None
                ),
            )
        except (Refusal, StateError) as exc:
            results.append(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                    "state": "could-not-classify",
                }
            )
        else:
            prepared.append((checkout, record, repository, proof, target, identity))
    identities = [identity for *_prefix, identity in prepared]
    if len(set(identities)) != len(identities):
        raise Refusal(
            "classify-ownerless-validate-batch resolved multiple checkouts to one directory"
        )
    budget = _ReadOnlyCommandBudget.start(
        timeout_seconds=_VALIDATE_REMOVE_BATCH_CENSUS_SECONDS,
        stdout_limit=16 * 1024 * 1024,
        stderr_limit=64 * 1024,
        input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
    )
    census_count = int(bool(prepared))
    if prepared:
        try:
            census = _capture_lsof_process_path_census(
                [target for *_prefix, target, _identity in prepared], budget=budget
            )
            budget.remaining_seconds()
        except Refusal as exc:
            results.extend(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                    "state": "could-not-classify",
                }
                for checkout, _record, _repo, _proof, _target, _identity in prepared
            )
            prepared = []
            census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    else:
        census = _ProcessPathCensus((), (), owner_cgroup_complete=False)
    batch = _OwnerlessValidationBatchContext(
        {identity: target for *_prefix, target, identity in prepared},
        census,
        budget,
    )
    actor = _read_process_identity(os.getpid())
    for checkout, record, repository, proof, target, _identity in prepared:
        try:
            budget.remaining_seconds()
            census.assert_slot_unused(target, None, ignore_current_process=False)
            if frozen and proof is None:
                historical = _frozen_no_proof_disposition(
                    config,
                    target,
                    record,
                    repository,
                    batch_cleanup=batch,
                )
                if historical.disposition is _FrozenNoProofDisposition.CURRENT_INCOMPLETE_RETAINED:
                    results.append({
                        "blocks_entry": False,
                        "checkout": checkout,
                        "reason": "current incomplete frozen validation is exact and inactive; the checkout and no-result remain retained",
                        "state": "current-incomplete-retained",
                    })
                    continue
                if (
                    historical.disposition
                    is _FrozenNoProofDisposition.HISTORICAL_NONBLOCKING
                ):
                    results.append(
                        {
                            "blocks_entry": False,
                            "checkout": checkout,
                            "reason": (
                                f"historical schema {historical.historical_schema} "
                                "validation is exact and inactive; it remains retained"
                            ),
                            "state": "historical-retained",
                        }
                    )
                    continue
                if historical.disposition is _FrozenNoProofDisposition.BLOCKS_ENTRY:
                    raise Refusal(
                        "frozen validation has no typed removal proof and cannot "
                        "be classified as historical"
                    )
            item_args = argparse.Namespace(
                ownerless_validate_checkout=None if frozen else checkout,
                ownerless_validate_cargo_home=None,
                frozen_validate_checkout=checkout if frozen else None,
                completed_record=record,
                repository=repository,
                validation_proof_manifest=proof,
                recovery_note=None,
            )
            _ownerless_validation_journal(
                config,
                item_args,
                actor,
                before_states,
                batch_cleanup=batch,
                require_remote_containment=False,
            )
        except (Refusal, StateError) as exc:
            results.append(
                {
                    "blocks_entry": True,
                    "checkout": checkout,
                    "reason": str(exc),
                    "state": "could-not-classify",
                }
            )
        else:
            results.append(
                {
                    "blocks_entry": False,
                    "checkout": checkout,
                    "reason": (
                        "terminal validation is exact and unused; read-only "
                        "classification left it retained"
                    ),
                    "state": "terminal-retained",
                }
            )
    after_states, after_archives = _validate_global_state(config)
    if before_rows != _global_rows(after_states, after_archives):
        raise Refusal("active registry changed during validation classification")
    if before_paths != tuple(row.path for row in create_rows):
        raise Refusal("recovery journal set changed before validation classification")
    _assert_create_journal_classifications_stable(
        config, create_rows, after_states, after_archives
    )
    payload = {
        "classifications": results,
        "create_journals": [row.to_obj() for row in create_rows],
        "process_censuses": census_count,
        "requested": len(checkouts),
        "schema": 1,
    }
    if args.format == "json":
        print(json.dumps(payload, sort_keys=True))
    else:
        blocking = sum(result["blocks_entry"] is True for result in results)
        print(
            f"requested={len(checkouts)} blocking={blocking} "
            f"nonblocking={len(results) - blocking} process_censuses={census_count}"
        )
        for result in results:
            print(
                f"{result['state']}: {result['checkout']} "
                f"blocks_entry={str(result['blocks_entry']).lower()} "
                f"reason={result['reason']}"
            )
    return 0


