def _read_regular_file_identity(
    path: Path, label: str, limit: int
) -> tuple[bytes, _RegularFileIdentity]:
    """Read one bounded regular file and bind the bytes to its open inode."""

    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise Refusal(f"cannot read {label} {path}: {exc}") from exc
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise Refusal(f"{label} is not a regular file: {path}")
        if before.st_size > limit:
            raise Refusal(f"{label} exceeds the {limit}-byte safety bound: {path}")
        chunks: list[bytes] = []
        remaining = limit + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 64 * 1024))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        contents = b"".join(chunks)
        after = os.fstat(descriptor)
        try:
            path_after = path.stat(follow_symlinks=False)
        except OSError as exc:
            raise Refusal(f"cannot recheck {label} path {path}: {exc}") from exc
    except Refusal:
        raise
    except OSError as exc:
        raise Refusal(f"cannot read {label} {path}: {exc}") from exc
    finally:
        os.close(descriptor)
    if len(contents) > limit:
        raise Refusal(f"{label} exceeds the {limit}-byte safety bound: {path}")
    stable_fields = (
        "st_dev",
        "st_ino",
        "st_mode",
        "st_size",
        "st_mtime_ns",
        "st_ctime_ns",
    )
    if any(getattr(before, field) != getattr(after, field) for field in stable_fields):
        raise Refusal(f"{label} changed while it was read: {path}")
    if any(
        getattr(after, field) != getattr(path_after, field)
        for field in stable_fields
    ):
        raise Refusal(f"{label} path changed while it was read: {path}")
    if len(contents) != after.st_size:
        raise Refusal(f"{label} size changed while it was read: {path}")
    return contents, _RegularFileIdentity(
        device=after.st_dev,
        inode=after.st_ino,
        size=after.st_size,
        sha256=hashlib.sha256(contents).hexdigest(),
    )


def _strict_json_object(contents: bytes, label: str) -> Mapping[str, object]:
    """Decode a JSON object while refusing duplicate keys at every depth."""

    def unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
        value: dict[str, object] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"duplicate key {key!r}")
            value[key] = item
        return value

    try:
        value = json.loads(contents, object_pairs_hook=unique_object)
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise Refusal(f"{label} is malformed JSON: {exc}") from exc
    return _as_mapping(value, label)


def _refuse_symlink(path: Path, label: str) -> None:
    try:
        if path.is_symlink():
            raise StateError(f"{label} must not be a symlink: {path}")
    except OSError as exc:
        raise StateError(f"cannot inspect {label} {path}: {exc}") from exc


def _relative_inside_reference(
    root: Path, raw: str, label: str
) -> tuple[str, Path]:
    """Validate a stored relative identity without inspecting its storage."""

    candidate = Path(raw)
    if candidate.is_absolute() or not candidate.parts or ".." in candidate.parts:
        raise Refusal(f"{label} must be a relative path inside {root}: {raw!r}")
    lexical = Path(os.path.normpath(str(candidate)))
    if lexical == Path("."):
        raise Refusal(f"{label} must not be the project root")
    return lexical.as_posix(), root / lexical


def _relative_inside(root: Path, raw: str, label: str) -> tuple[str, Path]:
    lexical, absolute = _relative_inside_reference(root, raw, label)
    _ensure_no_symlink_components(root, absolute, label)
    return lexical, absolute


def _ensure_no_symlink_components(root: Path, path: Path, label: str) -> None:
    try:
        relative = path.relative_to(root)
    except ValueError as exc:
        raise Refusal(f"{label} escapes the project root: {path}") from exc
    current = root
    for part in relative.parts:
        current = current / part
        try:
            if current.is_symlink():
                raise Refusal(f"{label} crosses a symlink: {current}")
        except OSError as exc:
            raise Refusal(f"cannot inspect {label} path {current}: {exc}") from exc


def _canonical_managed_file_path(
    config: Config,
    raw: str,
    label: str,
    *,
    allow_frozen: bool = False,
) -> tuple[str, Path]:
    """Resolve one exact managed file spelling without accepting aliases."""

    candidate = Path(raw)
    if candidate.is_absolute():
        if not allow_frozen or raw != os.path.normpath(raw) or ".." in candidate.parts:
            raise Refusal(f"{label} is not a canonical managed path: {raw!r}")
        frozen_root = _frozen_validation_directory(config)
        if not _path_is_within(candidate, frozen_root):
            raise Refusal(f"{label} is outside the managed validation roots: {raw!r}")
        _ensure_no_symlink_components(config.root.parent, candidate, label)
        return raw, candidate
    relative, path = _relative_inside(config.root, raw, label)
    if relative != raw:
        raise Refusal(
            f"{label} must use its canonical project-relative spelling: {relative!r}"
        )
    return relative, path

class _OwnerlessValidationBatchContext:
    """Shared full-host evidence plus fresh checks for private ownerless paths."""

    canonical_by_identity: Mapping[_PrivateCleanupIdentity, Path]
    shared_census: _ProcessPathCensus
    census_budget: _ReadOnlyCommandBudget
    same_uid_census_count: int = 0

    def assert_unused(
        self, config: Config, active: Path, *, fresh_same_uid: bool
    ) -> None:
        managed_root = (
            _frozen_validation_directory(config)
            if active.parent == _frozen_validation_directory(config)
            else None
        )
        identity = _private_cleanup_path_identity(
            config, active, allowed_modes={0o700}, managed_root=managed_root
        )
        canonical = self.canonical_by_identity.get(identity)
        if canonical is None:
            raise Refusal(
                f"private validation checkout identity was not in the shared census: {active}"
            )
        # Keep the ordinary explicit cwd guard for both the canonical and
        # renamed path without launching another process census.
        _assert_slot_unused(
            active,
            census=_ProcessPathCensus((), (), owner_cgroup_complete=False),
        )
        self.shared_census.assert_slot_unused(
            canonical, None, ignore_current_process=False
        )
        if not fresh_same_uid:
            return
        self.same_uid_census_count += 1
        fresh_budget = _ReadOnlyCommandBudget.start(
            timeout_seconds=self.census_budget.remaining_seconds(),
            stdout_limit=16 * 1024 * 1024,
            stderr_limit=64 * 1024,
            input_limit=_MOUNTINFO_CENSUS_BYTES_LIMIT,
        )
        fresh = _capture_same_uid_process_path_census(
            (active,), budget=fresh_budget
        )
        fresh.assert_slot_unused(active, None, ignore_current_process=False)
        self.census_budget.remaining_seconds()


@dataclasses.dataclass
class _OwnerlessValidationExclusion:
    """An ownerless validation tree hidden behind a root-owned directory."""

    root: Path
    guard: Path
